const fs = require('fs');

const [n, m] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const width = Math.min(n, m);
const height = Math.max(n, m);

const size = 1 << width;
const full = size - 1;
const INF = 1e9;

const popcount = new Int32Array(size);
const cover = new Int32Array(size);

for (let mask = 0; mask < size; mask++) {
    popcount[mask] = popcount[mask >> 1] + (mask & 1);
    cover[mask] = (mask | (mask << 1) | (mask >> 1)) & full;
}

let dp = new Int32Array(size * size);
dp.fill(INF);

for (let mask = 0; mask < size; mask++) {
    dp[mask] = popcount[mask];
}

for (let row = 1; row < height; row++) {
    const next = new Int32Array(size * size);
    next.fill(INF);

    for (let a = 0; a < size; a++) {
        for (let b = 0; b < size; b++) {
            const value = dp[a * size + b];
            if (value === INF) continue;

            for (let c = 0; c < size; c++) {
                if ((a | cover[b] | c) !== full) continue;

                const index = b * size + c;
                const candidate = value + popcount[c];
                if (candidate < next[index]) next[index] = candidate;
            }
        }
    }

    dp = next;
}

let minimumOccupied = INF;

for (let a = 0; a < size; a++) {
    for (let b = 0; b < size; b++) {
        if ((a | cover[b]) === full) {
            minimumOccupied = Math.min(minimumOccupied, dp[a * size + b]);
        }
    }
}

